188	
189	      if (input.searchType === 'semantic' || input.searchType === 'hybrid') {
190	        // Perform semantic search
191	        searchResults = await memoryService.semanticSearch(
192	          input.query,
193	          input.limit,
194	          input.minRelevance
195	        );
196	      } else {
197	        // Perform keyword search via query
198	        const entries = await memoryService.query({
199	          type: input.searchType === 'keyword' ? 'keyword' : 'hybrid',
200	          keyword: input.query,
201	          limit: input.limit,
202	          namespace: input.category,
203	        });
204	
205	        searchResults = entries.map(e => ({
206	          entry: e,
207	          score: 1.0, // Keyword match doesn't have a score
208	          distance: 0,
209	        }));
210	      }
211	
212	      // Convert to SearchResult format
213	      let results: SearchResult[] = searchResults.map(r => ({
214	        id: r.entry.id,
215	        content: r.entry.content,
216	        type: r.entry.type,
217	        category: r.entry.namespace,
218	        tags: r.entry.tags,
219	        importance: r.entry.metadata.importance as number,
220	        createdAt: r.entry.createdAt.toISOString(),
221	        accessedAt: r.entry.lastAccessedAt?.toISOString(),
222	        accessCount: r.entry.accessCount,
223	        relevance: r.score || (1 - r.distance),
224	        metadata: input.includeMetadata ? r.entry.metadata : undefined,
225	      }));
226	
227	      // Apply filters
228	      if (input.type !== 'all') {
229	        results = results.filter(m => m.type === input.type);
230	      }
231	      if (input.tags && input.tags.length > 0) {
232	        results = results.filter(m =>
233	          input.tags!.every(tag => m.tags?.includes(tag))
234	        );
235	      }
236	      if (input.minRelevance !== undefined) {
237	        results = results.filter(m => m.relevance >= input.minRelevance!);
238	      }
239	
240	      const executionTime = performance.now() - startTime;
241	
242	      return {
243	        results: results.slice(0, input.limit),
244	        total: results.length,
245	        query: input.query,
246	        searchType: input.searchType,
247	        executionTime,
248	      };
249	    } catch (error) {
250	      console.error('Failed to search memory via memory service:', error);
251	      // Fall through to simple implementation
252	    }
253	  }
254	
255	  // Simple implementation when no memory service is available
256	  const executionTime = performance.now() - startTime;
257	  return {
258	    results: [],
259	    total: 0,
260	    query: input.query,
261	    searchType: input.searchType,
262	    executionTime,
263	  };
264	}
